--[[
    14900850 茶杯猫 专用 SuperTimeline 脚本 
    开局播入场 clip, 跳入一个 loop clip, 等待玩家按某个按钮后, 进入对应 idle100 / idle200

]]--


---@class SuperTimeline_14900850_Enter           
local SuperTimeline_14900850_Enter = Class('SuperTimeline_14900850_Enter')

-- 外部访问时使用:
-- ---@type SuperTimeline_14900850_Enter
-- local SuperTimeline_14900850_Enter = import('Game.IdolLive3D.Interactive.Customs.SuperTimeline_14900850_Enter')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Time = CS.UnityEngine.Time

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type IdolLive3D_States
local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
local IdleType = IdolLive3D_States.IdleType


local IdolLive3D_Input = import("Game.IdolLive3D.IdolLive3D_Input")

local CriWareUtils_ = import('Game.Entry.CriWareUtilsFix')

---@type Live3D_CustomEvents
local Live3D_CustomEvents = import('Game.IdolLive3D.Interactive.Customs.Live3D_CustomEvents')


-- ========================================================

-- local bgm_sheet = "Audio/bgm_live3d_pub"
-- local bgm_cue_tl = "bgm_live3d_pub_tl"
-- local bgm_cue    = "bgm_live3d_pub"

-- ========================================================

---@param idolLive3D_SuperTimeLineState_ table
function SuperTimeline_14900850_Enter:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil -- 最后一次登记的 clipId
    self.isPlayFullScreenFXFadeIn = false

    -- local allResources = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager.allResources
    -- self.fullScreenFXEnv = allResources.fullScreenFXEnvs["_FullBlack_"]

    self.nextClipInfosMap = {}
end




-- 需手动调用 Delete()
function SuperTimeline_14900850_Enter:__delete()

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil

    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = nil

    IdolLive3D_Utils.StopCoroutine(self.co_3)
    self.co_3 = nil

    IdolLive3D_Utils.StopCoroutine(self.co_4)
    self.co_4 = nil
    --self.fullScreenFXEnv:Delete()
end



function SuperTimeline_14900850_Enter:StartPlay() 
    self.isPlayFullScreenFXFadeIn = false
end 


-- ---@param clipJson_ table @ c# class SuperTimelineClip 内数据
-- ---@param timelineStateEnv_ table
function SuperTimeline_14900850_Enter:SelfUpdate( clipJson_, timelineStateEnv_ ) 

    local clipId = tostring(clipJson_.clipId)
    local isFirstFrame = (clipId ~= self.lastClipId)
    self.lastClipId = clipId


    if clipId == "102" then 
        -- 只有 clip "102" 是带逻辑的 
        assert( table.count(clipJson_.nextClipInfos) > 0 )

        if isFirstFrame == true then 
            -- local clipDuration = timelineStateEnv_.play.duration -- timeline clip 总时长
            -- local countDownDuration = 5 -- 倒计时总时长, 允许它比 clipDuration 长;            
            ---
            self.nextClipInfosMap = {}
            for _,nextClipInfo in pairs(clipJson_.nextClipInfos) do 
                assert( string.isEmpty(nextClipInfo.conditionKey) == false )
                self.nextClipInfosMap[string.lower(nextClipInfo.conditionKey)] = nextClipInfo
            end

            Events.Broadcast(Live3D_CustomEvents.Init_StartTwoIdlesChoose, 
                -- idle 100 cb_:
                function()
                    local nextClipInfo = self.nextClipInfosMap["103"]
                    self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )
                end, 
                -- idle 200 cb_:
                function()
                    local nextClipInfo = self.nextClipInfosMap["104"]
                    self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )
                end
            )
        end  
    end
    
    -----
    if  self.isPlayFullScreenFXFadeIn == false then 
        local remainTime = timelineStateEnv_.play.duration - timelineStateEnv_.play.playTime

        if clipId == "103" or clipId == "104" then
            if remainTime < 0.5  then 
                self.isPlayFullScreenFXFadeIn = true

                IdolLive3D_Utils.StopCoroutine(self.co_4)
                self.co_4 = cs_coroutine.start(function() -- !!!! 晚点用上 marker...

                    local idolLive3D_InteractiveManager = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager
                    cs_coroutine.yield_return( idolLive3D_InteractiveManager.fullScreenFXEnv:FadeIn(0.3) ) --- 全屏特效 淡入
                end)
            end 
        end
    end 

    ---
    if clipId ~= "102" then 
        --- None,Hold 模式就是唯一一遍尾后帧,
        if timelineStateEnv_.play.loopInteger > 0 then 
            local nextClipInfosNum = table.count(clipJson_.nextClipInfos)
            
            if nextClipInfosNum == 0 then
                self:EndPLay( clipJson_, timelineStateEnv_ )
                
            elseif nextClipInfosNum == 1 then
                print("无条件 跳入下一个 clip" )
                local nextClipInfo = clipJson_.nextClipInfos[1]
                self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )
            else 
                printError("暂不支持在此情况下存在多个 nextClipInfos")
            end
        end 
    end 
end




---@param clipJson_ table @ c# class SuperTimelineClip 内数据
---@param timelineStateEnv_ table
function SuperTimeline_14900850_Enter:EndPLay( clipJson_, timelineStateEnv_ ) 
    --printError("EndPLay")

    local idolLive3D_InteractiveManager = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager
    local clipId = tostring(clipJson_.clipId)

    self.idolLive3D_SuperTimeLineState.isPlaying = false

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(function()

        cs_coroutine.yield_return( idolLive3D_InteractiveManager.fullScreenFXEnv:WaitTargetState( IdolLive3D_States.FullScreenFXState.Show ) ) -- 等待 fadeIn 结束

        self.idolLive3D_SuperTimeLineState:EndPLay()

        -- 这段几乎不需要等待:
        local isWaited = false
        for i=0, 500 do 
            if isNotNull(idolLive3D_InteractiveManager:FindCurrentPlayingIdleState()) then
                isWaited = true
                break
            end 
            coroutine.yield(Yielders.EndOfFrame)
        end 
        if isWaited == false then 
            printError("始终没等到 CameraMode.FreeManual")
        end
        ---
        if clipId == "103" then
            --printError("end -2-")
            --CriWareUtils_.PlayMusic( bgm_sheet, bgm_cue )
            idolLive3D_InteractiveManager:ForceToTargetIdle( IdleType.Type_100 )
            Events.Broadcast(Live3D_CustomEvents.Init_IntoIdle100, nil)

        elseif clipId == "104" then
            --printError("end -4-")
            --CriWareUtils_.PlayMusic( bgm_sheet, bgm_cue )
            idolLive3D_InteractiveManager:ForceToTargetIdle( IdleType.Type_200 )
            Events.Broadcast(Live3D_CustomEvents.Init_IntoIdle200, nil)
        end 
    end)
end



return SuperTimeline_14900850_Enter
